---
import { getCollection } from 'astro:content';
import Layout from '../../layouts/Layout.astro';

const books = (await getCollection('books')).sort((a, b) =>
  a.data.title < b.data.title ? -1 : a.data.title > b.data.title ? 1 : 0,
);
const tags = [...new Set(books.flatMap((b) => b.data.tags))].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
---

<Layout title="Books | Bookshelf">
  <h1>All books</h1>
  <div role="group" aria-label="Filter by tag" id="filter">
    <button type="button" aria-pressed="true" data-tag="">All</button>
    {tags.map((t) => <button type="button" aria-pressed="false" data-tag={t}>{t}</button>)}
  </div>
  <ul aria-label="Books" id="books">
    {
      books.map((b) => (
        <li data-slug={b.id} data-tags={JSON.stringify(b.data.tags)}>
          <a href={`/books/${b.id}`}>{b.data.title}</a>
          <span>{b.data.author}, {b.data.year}</span>
          <strong class="fav" hidden>Favorite</strong>
        </li>
      ))
    }
  </ul>
</Layout>

<script>
  let favs: string[] = [];
  try {
    favs = JSON.parse(localStorage.getItem('favorites') || '[]');
  } catch {}
  const items = document.querySelectorAll<HTMLElement>('#books li');
  items.forEach((li) => {
    const fav = li.querySelector<HTMLElement>('.fav');
    if (fav && favs.includes(li.dataset.slug!)) fav.hidden = false;
    else fav?.remove();
  });
  const buttons = document.querySelectorAll<HTMLButtonElement>('#filter button');
  buttons.forEach((btn) =>
    btn.addEventListener('click', () => {
      buttons.forEach((b) => b.setAttribute('aria-pressed', String(b === btn)));
      const tag = btn.dataset.tag;
      items.forEach((li) => {
        li.hidden = !!tag && !(JSON.parse(li.dataset.tags!) as string[]).includes(tag);
      });
    }),
  );
</script>
