    <Layout title={`${entry.data.title} | Bookshelf`}>
      <h1>{entry.data.title}</h1>
      <p>by {entry.data.author}</p>
      <p>Published in {entry.data.year}</p>
      <p>Rating: {entry.data.rating}/5</p>
      <ul>
        {entry.data.tags.map((t) => <li><a href="/books">{t}</a></li>)}
      </ul>
      <div><Content /></div>
      <button type="button" id="fav" data-slug={entry.id}>Add to favorites</button>
    </Layout>
  ) : (
    <NotFound />
  )
}

<script>
  const btn = document.querySelector<HTMLButtonElement>('#fav');
  if (btn) {
    const slug = btn.dataset.slug!;
    const read = (): string[] => {
      try {
        return JSON.parse(localStorage.getItem('favorites') || '[]');
      } catch {
        return [];
      }
    };
    const render = () => {
      btn.textContent = read().includes(slug) ? 'Remove from favorites' : 'Add to favorites';
    };
    btn.addEventListener('click', () => {
      const f = read();
      const next = f.includes(slug) ? f.filter((s) => s !== slug) : [...f, slug];
      localStorage.setItem('favorites', JSON.stringify(next));
      render();
    });
    render();
  }
</script>
