---
import Layout from '../layouts/Layout.astro';
import { validateContact, type ContactErrors } from '../lib/validate';

let values = { name: '', email: '', message: '' };
let errors: ContactErrors = {};
let success = '';
if (Astro.request.method === 'POST') {
  const form = await Astro.request.formData();
  const get = (k: string) => String(form.get(k) ?? '');
  values = { name: get('name'), email: get('email'), message: get('message') };
  errors = validateContact(values);
  if (Object.keys(errors).length === 0) success = `Thanks, ${values.name.trim()}! Your message has been sent.`;
}
---

<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  <div id="contact">
    {success && <p id="success">{success}</p>}
    {
      !success && (
        <form method="post" action="/contact" novalidate>
          <div>
            <label for="name">Name</label>
            <input type="text" id="name" name="name" value={values.name} />
            {errors.name && <span class="error" data-for="name">{errors.name}</span>}
          </div>
          <div>
            <label for="email">Email</label>
            <input type="email" id="email" name="email" value={values.email} />
            {errors.email && <span class="error" data-for="email">{errors.email}</span>}
          </div>
          <div>
            <label for="message">Message</label>
            <textarea id="message" name="message">{values.message}</textarea>
            {errors.message && <span class="error" data-for="message">{errors.message}</span>}
          </div>
          <button type="submit">Send</button>
        </form>
      )
    }
  </div>
</Layout>

<script>
  import { validateContact } from '../lib/validate';

  const box = document.querySelector<HTMLElement>('#contact')!;
  box.addEventListener('submit', async (e) => {
    const form = e.target as HTMLFormElement;
    e.preventDefault();
    const data = new FormData(form);
    const get = (k: string) => String(data.get(k) ?? '');
    const errors = validateContact({ name: get('name'), email: get('email'), message: get('message') });
    form.querySelectorAll('.error').forEach((n) => n.remove());
    const keys = Object.keys(errors) as (keyof typeof errors)[];
    if (keys.length) {
      for (const k of keys) {
        const span = document.createElement('span');
        span.className = 'error';
        span.dataset.for = k;
        span.textContent = errors[k]!;
        form.querySelector(`[name="${k}"]`)?.after(span);
      }
      return;
    }
    const res = await fetch(form.action, { method: 'POST', body: new URLSearchParams(data as any) });
    const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
    const next = doc.querySelector('#contact');
    if (next) box.innerHTML = next.innerHTML;
  });
</script>
